 body.pf-game.playing #mobileCue:not([hidden]){display:block;position:fixed;z-index:25;left:50%;top:calc(var(--pf-header-height) + var(--status-height,60px) + 10px);transform:translateX(-50%);max-width:calc(100vw - 24px);padding:4px 8px;border:1px solid #ddc477;border-radius:6px;background:#193b40f2;color:#fff0b1;font:700 13px/1.3 system-ui;text-align:center;pointer-events:none}
